(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:'',notifications:[],reviews:[]};
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('../../../api/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Unable to load updates.');return data;}
  function status(text,error=false){el('vcom-status').textContent=text;el('vcom-status').className='vc-status '+(error?'warning':'info');}
  function item(title,description){const row=document.createElement('div');row.className='vc-list-item';const copy=document.createElement('div');copy.className='vc-list-copy';const strong=document.createElement('strong');strong.textContent=title;const p=document.createElement('p');p.textContent=description;copy.append(strong,p);row.append(copy);return row;}
  function render(){const notices=el('vcom-notifications');notices.replaceChildren();if(!state.notifications.length)notices.textContent='No notifications yet.';state.notifications.forEach(n=>{const row=item(n.title,n.message);const time=document.createElement('small');time.textContent=n.created_at+(n.read_at?' · Read':' · Unread');row.append(time);notices.append(row);});const reviews=el('vcom-reviews');reviews.replaceChildren();if(!state.reviews.length)reviews.textContent='No product reviews yet.';state.reviews.forEach(r=>{const row=item(r.product_name+' · '+r.first_name+' '+r.last_name,r.review_text||r.body||r.comment||'');const detail=document.createElement('small');detail.textContent='Rating: '+r.rating+' / 5'+(r.vendor_reply?' · Your reply: '+r.vendor_reply:'');row.append(detail);if(r.status==='published'&&!r.vendor_reply){const button=document.createElement('button');button.type='button';button.className='vc-btn small';button.textContent='Reply';button.addEventListener('click',()=>{el('vcom-form').reset();el('vcom-form').elements.namedItem('review_id').value=r.id;el('vcom-dialog').showModal();});row.append(button);}reviews.append(row);});status(state.notifications.length+' notifications · '+state.reviews.length+' reviews');}
  async function load(){try{const [identity,notifications,reviews]=await Promise.all([call('vendor/auth/me.php'),call('notifications.php?limit=100'),call('vendor/reviews.php')]);state.csrf=identity.csrf_token||'';state.notifications=notifications.notifications||[];state.reviews=reviews.reviews||[];render();}catch(error){status(error.message,true);}}
  el('vcom-read-all').addEventListener('click',async()=>{try{await call('notifications.php','PATCH',{id:'all'});await load();}catch(error){status(error.message,true);}});
  el('vcom-close').addEventListener('click',()=>el('vcom-dialog').close());
  el('vcom-form').addEventListener('submit',async event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const button=event.submitter;button.disabled=true;try{await call('vendor/reviews.php','POST',Object.fromEntries(new FormData(event.currentTarget)));el('vcom-dialog').close();await load();}catch(error){status(error.message,true);}finally{button.disabled=false;}});
  load();
})();
